import { tool, createSdkMcpServer } from "@anthropic-ai/claude-agent-sdk";
import { z } from "zod";

const checkOrderStatus = tool(
  "check_order_status",
  "Consulta de solo lectura del estado de una orden (pending, shipped, delivered, " +
    "refunded, cancelled) y su historial de pagos. No tiene efectos secundarios — " +
    "usar SIEMPRE antes de process_refund o issue_partial_credit para confirmar que " +
    "la orden existe y está en un estado elegible.",
  { order_id: z.string().describe("ID de orden, formato ORD-XXXXXX") },
  async ({ order_id }) => {
    const order = await lookupOrder(order_id);
    if (!order) {
      return { content: [{ type: "text", text: `No existe ninguna orden con ID ${order_id}.` }], isError: true };
    }
    return { content: [{ type: "text", text: JSON.stringify(order) }] };
  }
);

const processRefund = tool(
  "process_refund",
  "Emite un reembolso COMPLETO del monto original de la orden, devuelto al método " +
    "de pago original. Usar SOLO cuando el cliente pide anular la compra por completo " +
    "(producto no recibido, cancelación total, cargo duplicado). NO usar para " +
    "descuentos parciales ni compensaciones por inconvenientes menores — para eso " +
    "existe issue_partial_credit. Precondición: la orden debe estar en estado " +
    "'shipped' o 'delivered' (verificar con check_order_status primero). Reembolsos " +
    "por encima del umbral configurado son bloqueados antes de ejecutarse — ver el " +
    "hook PreToolUse del Paso 4.",
  {
    order_id: z.string().describe("ID de orden, formato ORD-XXXXXX"),
    amount: z.number().describe("Monto a reembolsar en USD — debe coincidir con el monto real de la orden"),
    reason: z.enum(["not_received", "duplicate_charge", "full_cancellation", "other"]),
  },
  async ({ order_id, amount, reason }) => {
    // El hook PreToolUse ya bloqueó esta llamada si amount > 500 — acá solo llega
    // el caso permitido.
    await issueRefund(order_id, amount);
    return { content: [{ type: "text", text: `Reembolso de $${amount} procesado para la orden ${order_id}.` }] };
  }
);

const issuePartialCredit = tool(
  "issue_partial_credit",
  "Emite un CRÉDITO DE TIENDA parcial (no reembolso a método de pago original) " +
    "como compensación por un inconveniente menor (demora en el envío, empaque " +
    "dañado pero producto utilizable, error menor de facturación). El monto máximo " +
    "por llamada es 50 USD equivalente. NO usar si el cliente pide su dinero de " +
    "vuelta explícitamente — en ese caso es process_refund o escalate_to_human, no esta " +
    "herramienta.",
  {
    customer_id: z.string(),
    amount_usd: z.number().max(50).describe("Monto en USD, máximo 50"),
    reason: z.enum(["shipping_delay", "minor_damage", "billing_error"]),
  },
  async ({ customer_id, amount_usd, reason }) => {
    await creditAccount(customer_id, amount_usd);
    return { content: [{ type: "text", text: `$${amount_usd} de crédito emitido para el cliente ${customer_id}.` }] };
  }
);

const escalateToHuman = tool(
  "escalate_to_human",
  "Transfiere la conversación a un agente humano preservando el contexto completo. " +
    "Usar cuando: (a) la solicitud cae fuera de la política definida para las demás " +
    "herramientas, (b) el cliente pide explícitamente hablar con una persona, o (c) " +
    "una llamada a process_refund fue bloqueada por exceder el umbral autorizado. " +
    "Esta es la única salida válida para casos ambiguos.",
  {
    summary: z.string().describe("Resumen del caso para el agente humano"),
    urgency: z.enum(["low", "normal", "high"]).default("normal"),
  },
  async ({ summary, urgency }) => {
    const ticketId = await createEscalationTicket(summary, urgency);
    return { content: [{ type: "text", text: `Caso escalado. Ticket ${ticketId} creado con urgencia ${urgency}.` }] };
  }
);

export const supportServer = createSdkMcpServer({
  name: "support",
  version: "1.0.0",
  tools: [checkOrderStatus, processRefund, issuePartialCredit, escalateToHuman],
});
// Cada tool queda expuesta al modelo como mcp__support__<nombre>,
// ej. mcp__support__process_refund.

// Esto es lo que query() hace internamente en cada turno — no es código
// que el usuario del Agent SDK escribe, es la mecánica que justifica por
// qué el SDK puede abstraer el loop sin cambiar el comportamiento:
//
//   1. Enviar la conversación a Claude.
//   2. Si stop_reason === 'tool_use': ejecutar las tools pedidas,
//      reinyectar los tool_result, volver a 1.
//   3. Si stop_reason === 'end_turn': terminar y entregar el resultado.
//
// Como consumidor del SDK, no ves el paso 1-2 turno por turno — consumís
// el stream de mensajes y el stop_reason terminal llega en el resultado.

import { query } from "@anthropic-ai/claude-agent-sdk";
import { supportServer } from "../mcp/support-server";
import { blockLargeRefunds } from "./hooks"; // ver Paso 4

export async function runSupportAgent(userMessage: string) {
  for await (const message of query({
    prompt: userMessage,
    options: {
      mcpServers: { support: supportServer },
      allowedTools: ["mcp__support__*"],
      hooks: {
        PreToolUse: [{ matcher: "mcp__support__process_refund", hooks: [blockLargeRefunds] }],
      },
    },
  })) {
    // message.type es 'assistant' | 'user' | 'result' | ... — stop_reason
    // NO aparece acá, solo en el mensaje 'result' final.
    if (message.type === "result") {
      if (message.subtype === "success") {
        console.log(message.result);
      } else {
        // 'error_max_turns' | 'error_max_budget_usd' | 'error_during_execution' | ...
        console.error(`Sesión terminó sin éxito: ${message.subtype}`);
      }
      console.log("stop_reason:", message.stop_reason); // 'end_turn' esperado
      return message;
    }
  }
}

export type ErrorCategory = "transient" | "validation" | "business" | "permission";

export interface StructuredToolError {
  errorCategory: ErrorCategory;
  isRetryable: boolean;
  message: string;
}

export function buildErrorContent(category: ErrorCategory, message: string) {
  const error: StructuredToolError = {
    errorCategory: category,
    isRetryable: category === "transient",
    message,
  };
  // El texto lleva el JSON estructurado — el flag isError vive un nivel
  // arriba, en el objeto que retorna la tool (ver Paso 1 y Paso 4).
  return { content: [{ type: "text" as const, text: JSON.stringify(error) }], isError: true };
}

