import type { HookCallback, PreToolUseHookInput } from "@anthropic-ai/claude-agent-sdk";

const REFUND_ESCALATION_THRESHOLD_USD = 500;

export const blockLargeRefunds: HookCallback = async (input, _toolUseID, _opts) => {
  const preInput = input as PreToolUseHookInput;

  if (preInput.tool_name !== "mcp__support__process_refund") {
    return {}; // no es la tool que nos interesa: no intervenir
  }

  const toolInput = preInput.tool_input as { order_id: string; amount: number };

  // Fuente de verdad: el monto real de la orden en la base de datos, NO el
  // campo `amount` que el modelo incluyó en el input — el hook nunca debe
  // validar una regla de negocio contra un dato que el propio modelo
  // controla, porque eso reintroduce la superficie de fallo probabilística
  // que el hook existe para eliminar.
  const order = await lookupOrderAmount(toolInput.order_id);

  if (order.amount_usd > REFUND_ESCALATION_THRESHOLD_USD) {
    return {
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        permissionDecision: "deny",
        permissionDecisionReason:
          `Reembolso de $${order.amount_usd} excede el umbral autorizado de ` +
          `$${REFUND_ESCALATION_THRESHOLD_USD}. No reintentar process_refund para esta ` +
          `orden — usá escalate_to_human con el detalle del caso.`,
      },
    };
  }

  return {}; // dentro del umbral: se permite que la tool corra
};

